WITH parsed AS (SELECT id, created_at, coupon_codes, items, attributes, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, SIZE(items) AS num_items, TRANSFORM(items, i -> i.product_id) AS product_ids, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg FROM carts) SELECT id, created_at, coupon_codes, has_welcome_code, weight_kg, SUM(num_items) OVER (ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_num_items, NTILE(5) OVER (ORDER BY weight_kg DESC, id) AS weight_kg_bucket, SUM(weight_kg) OVER (ORDER BY weight_kg, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_weight_kg FROM parsed WHERE num_items IS NULL
